package org.apache.commons.math.optimization.general;

import java.io.*;
import java.math.*;
import java.util.*;
import java.util.Arrays;
import org.apache.commons.math.FunctionEvaluationException;
import org.apache.commons.math.optimization.OptimizationException;
import org.apache.commons.math.optimization.VectorialPointValuePair;
import org.apache.commons.math3.fitting.WeightedObservedPoints;
import org.apache.commons.math3.fitting.leastsquares.LeastSquaresOptimizer;
import org.apache.commons.math3.fitting.leastsquares.LeastSquaresProblem;
import org.apache.commons.math3.fitting.leastsquares.MultivariateJacobianFunction;
import org.apache.commons.math3.fitting.leastsquares.WeightedObservedPoint;
import org.apache.commons.math3.linear.DiagonalMatrix;
import org.apache.commons.math3.linear.RealMatrix;
import org.apache.commons.math3.optim.nonlinear.scalar.GoalType;
import org.apache.commons.math3.optimization.InitialGuess;
import org.apache.commons.math3.optimization.PointValuePair;
import org.apache.commons.math3.optimization.RealVector;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.mockito.Mockito.*;

/**
 * Test class for LevenbergMarquardtOptimizer.doOptimize().
 * Since doOptimize is protected, we use a subclass to expose it for testing.
 */
public class LevenbergMarquardtOptimizer_doOptimize_TriageGen1Test {

    /**
     * Testable subclass to access the protected doOptimize method.
     */
    private static class TestableLevenbergMarquardtOptimizer extends LevenbergMarquardtOptimizer {
        public VectorialPointValuePair doOptimizeExposed() throws Exception {
            return super.doOptimize();
        }

        // Helper to inject state if needed via reflection or if we were mocking internal state
        // However, for a real optimizer, we provide a valid problem.
    }

    @Test
    public void testDoOptimize_Convergence_SimpleLinear() throws Exception {
        // Minimize f(x) = (x - 2)^2. Residual = x - 2.
        // Jacobian = 1.
        MultivariateJacobianFunction function = point -> {
            double x = point.getEntry(0);
            RealVector residual = new org.apache.commons.math3.linear.ArrayRealVector(new double[]{x - 2.0});
            RealMatrix jacobian = new org.apache.commons.math3.linear.Array2DRowRealMatrix(new double[][]{{1.0}});
            return new org.apache.commons.math3.fitting.leastsquares.LevenbergMarquardtJacobian(residual, jacobian);
        };

        LeastSquaresProblem problem = new org.apache.commons.math3.fitting.leastsquares.LeastSquaresBuilder()
                .model(function)
                .target(new org.apache.commons.math3.linear.ArrayRealVector(new double[]{0.0}))
                .start(new org.apache.commons.math3.linear.ArrayRealVector(new double[]{0.0}))
                .weight(new DiagonalMatrix(new double[]{1.0}))
                .maxIterations(100)
                .build();

        LevenbergMarquardtOptimizer optimizer = new LevenbergMarquardtOptimizer();
        PointValuePair solution = optimizer.optimize(problem);

        assertEquals(2.0, solution.getPoint().getEntry(0), 1e-6);
    }

    @Test
    public void testDoOptimize_Convergence_MultiVariable() throws Exception {
        // Minimize f(x,y) = (x-1)^2 + (y-2)^2
        MultivariateJacobianFunction function = point -> {
            double x = point.getEntry(0);
            double y = point.getEntry(1);
            RealVector residual = new org.apache.commons.math3.linear.ArrayRealVector(new double[]{x - 1.0, y - 2.0});
            RealMatrix jacobian = new org.apache.commons.math3.linear.Array2DRowRealMatrix(new double[][]{
                    {1.0, 0.0},
                    {0.0, 1.0}
            });
            return new org.apache.commons.math3.fitting.leastsquares.LevenbergMarquardtJacobian(residual, jacobian);
        };

        LeastSquaresProblem problem = new org.apache.commons.math3.fitting.leastsquares.LeastSquaresBuilder()
                .model(function)
                .target(new org.apache.commons.math3.linear.ArrayRealVector(new double[]{0.0, 0.0}))
                .start(new org.apache.commons.math3.linear.ArrayRealVector(new double[]{0.0, 0.0}))
                .maxIterations(100)
                .build();

        LevenbergMarquardtOptimizer optimizer = new LevenbergMarquardtOptimizer();
        PointValuePair solution = optimizer.optimize(problem);

        assertEquals(1.0, solution.getPoint().getEntry(0), 1e-6);
        assertEquals(2.0, solution.getPoint().getEntry(1), 1e-6);
    }

    @Test(expected = org.apache.commons.math3.optim.unconverged.UnconvergedException.class)
    public void testDoOptimize_NoConvergence_MaxIterations() throws Exception {
        // Problem that won't converge within 1 iteration
        MultivariateJacobianFunction function = point -> {
            RealVector res = new org.apache.commons.math3.linear.ArrayRealVector(new double[]{point.getEntry(0) * 10});
            RealMatrix jac = new org.apache.commons.math3.linear.Array2DRowRealMatrix(new double[][]{{10.0}});
            return new org.apache.commons.math3.fitting.leastsquares.LevenbergMarquardtJacobian(res, jac);
        };

        LeastSquaresProblem problem = new org.apache.commons.math3.fitting.leastsquares.LeastSquaresBuilder()
                .model(function)
                .target(new org.apache.commons.math3.linear.ArrayRealVector(new double[]{0.0}))
                .start(new org.apache.commons.math3.linear.ArrayRealVector(new double[]{100.0}))
                .maxIterations(1)
                .build();

        LevenbergMarquardtOptimizer optimizer = new LevenbergMarquardtOptimizer();
        optimizer.optimize(problem);
    }

    @Test
    public void testTolerances_Setting() {
        LevenbergMarquardtOptimizer optimizer = new LevenbergMarquardtOptimizer();
        // We test that setters don't throw exceptions
        optimizer.setCostRelativeTolerance(1e-10);
        optimizer.setParRelativeTolerance(1e-10);
        optimizer.setOrthoTolerance(1e-10);
        optimizer.setInitialStepBoundFactor(1.0);
    }

    @Test
    public void testDoOptimize_ZeroResiduals_ImmediateConvergence() throws Exception {
        // If the starting point is already the solution
        MultivariateJacobianFunction function = point -> {
            RealVector residual = new org.apache.commons.math3.linear.ArrayRealVector(new double[]{0.0});
            RealMatrix jacobian = new org.apache.commons.math3.linear.Array2DRowRealMatrix(new double[][]{{1.0}});
            return new org.apache.commons.math3.fitting.leastsquares.LevenbergMarquardtJacobian(residual, jacobian);
        };

        LeastSquaresProblem problem = new org.apache.commons.math3.fitting.leastsquares.LeastSquaresBuilder()
                .model(function)
                .target(new org.apache.commons.math3.linear.ArrayRealVector(new double[]{0.0}))
                .start(new org.apache.commons.math3.linear.ArrayRealVector(new double[]{5.0}))
                .build();

        LevenbergMarquardtOptimizer optimizer = new LevenbergMarquardtOptimizer();
        PointValuePair solution = optimizer.optimize(problem);

        assertEquals(0.0, solution.getCost(), 1e-12);
    }

    /**
     * This test targets the logic branches related to the ratio and delta updates.
     * Since the internal logic is complex and highly dependent on the Jacobian,
     * we simulate a scenario where the ratio might be low to trigger the "failed iteration" logic.
     */
    @Test
    public void testDoOptimize_FailedIteration_Logic() throws Exception {
        // We use a function that is extremely non-linear to force the LM parameter to adjust
        MultivariateJacobianFunction function = point -> {
            double x = point.getEntry(0);
            // A very steep function: f(x) = x^4 -> residual = x^2
            // Jacobian = 2x
            RealVector residual = new org.apache.commons.math3.linear.ArrayRealVector(new double[]{x * x});
            RealMatrix jacobian = new org.apache.commons.math3.linear.Array2DRowRealMatrix(new double[][]{{2.0 * x}});
            return new org.apache.commons.math3.fitting.leastsquares.LevenbergMarquardtJacobian(residual, jacobian);
        };

        LeastSquaresProblem problem = new org.apache.commons.math3.fitting.leastsquares.LeastSquaresBuilder()
                .model(function)
                .target(new org.apache.commons.math3.linear.ArrayRealVector(new double[]{0.0}))
                .start(new org.apache.commons.math3.linear.ArrayRealVector(new double[]{1.0}))
                .maxIterations(50)
                .build();

        LevenbergMarquardtOptimizer optimizer = new LevenbergMarquardtOptimizer();
        PointValuePair solution = optimizer.optimize(problem);

        assertTrue(solution.getPoint().getEntry(0) < 1.0);
    }
}
